diff --git a/infra/environments/prod/ecs.tf b/infra/environments/prod/ecs.tf
new file mode 100644
index 0000000..4e19008
--- /dev/null
+++ b/infra/environments/prod/ecs.tf
@@ -0,0 +1,3 @@
+resource "aws_ecs_cluster" "trader" {
+  name = local.name_prefix
+}
diff --git a/infra/environments/prod/iam.tf b/infra/environments/prod/iam.tf
new file mode 100644
index 0000000..b4d5a55
--- /dev/null
+++ b/infra/environments/prod/iam.tf
@@ -0,0 +1,120 @@
+data "aws_iam_policy_document" "ecs_tasks_assume_role" {
+  statement {
+    effect  = "Allow"
+    actions = ["sts:AssumeRole"]
+
+    principals {
+      type        = "Service"
+      identifiers = ["ecs-tasks.amazonaws.com"]
+    }
+
+    condition {
+      test     = "StringEquals"
+      variable = "aws:SourceAccount"
+      values   = [var.aws_account_id]
+    }
+
+    condition {
+      test     = "ArnLike"
+      variable = "aws:SourceArn"
+      values   = ["arn:aws:ecs:${var.aws_region}:${var.aws_account_id}:*"]
+    }
+  }
+}
+
+resource "aws_iam_role" "task_execution" {
+  name               = "${local.name_prefix}-task-execution"
+  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
+}
+
+data "aws_iam_policy_document" "task_execution" {
+  statement {
+    sid       = "EcrAuthorization"
+    effect    = "Allow"
+    actions   = ["ecr:GetAuthorizationToken"]
+    resources = ["*"]
+  }
+
+  statement {
+    sid    = "PullTraderImage"
+    effect = "Allow"
+    actions = [
+      "ecr:BatchCheckLayerAvailability",
+      "ecr:GetDownloadUrlForLayer",
+      "ecr:BatchGetImage",
+    ]
+    resources = [aws_ecr_repository.trader.arn]
+  }
+
+  statement {
+    sid    = "WriteTraderLogs"
+    effect = "Allow"
+    actions = [
+      "logs:CreateLogStream",
+      "logs:PutLogEvents",
+    ]
+    resources = ["${aws_cloudwatch_log_group.trader.arn}:*"]
+  }
+
+  statement {
+    sid       = "ReadRuntimeSecret"
+    effect    = "Allow"
+    actions   = ["secretsmanager:GetSecretValue"]
+    resources = [aws_secretsmanager_secret.runtime.arn]
+  }
+}
+
+resource "aws_iam_role_policy" "task_execution" {
+  name   = "${local.name_prefix}-task-execution"
+  role   = aws_iam_role.task_execution.id
+  policy = data.aws_iam_policy_document.task_execution.json
+}
+
+resource "aws_iam_role" "trader" {
+  name               = "${local.name_prefix}-trader-task"
+  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
+}
+
+data "aws_iam_policy_document" "trader" {
+  statement {
+    sid    = "OperationalState"
+    effect = "Allow"
+    actions = [
+      "dynamodb:DescribeTable",
+      "dynamodb:GetItem",
+      "dynamodb:PutItem",
+      "dynamodb:Query",
+      "dynamodb:TransactWriteItems",
+    ]
+    resources = [aws_dynamodb_table.operational.arn]
+  }
+
+  statement {
+    sid    = "ListArchive"
+    effect = "Allow"
+    actions = [
+      "s3:GetBucketLocation",
+      "s3:ListBucket",
+      "s3:ListBucketMultipartUploads",
+    ]
+    resources = [aws_s3_bucket.archive.arn]
+  }
+
+  statement {
+    sid    = "ArchiveObservations"
+    effect = "Allow"
+    actions = [
+      "s3:GetObject",
+      "s3:PutObject",
+      "s3:AbortMultipartUpload",
+      "s3:ListMultipartUploadParts",
+    ]
+    resources = ["${aws_s3_bucket.archive.arn}/*"]
+  }
+}
+
+resource "aws_iam_role_policy" "trader" {
+  name   = "${local.name_prefix}-trader"
+  role   = aws_iam_role.trader.id
+  policy = data.aws_iam_policy_document.trader.json
+}
