+              </li>
+            ))}
+          </ol>
+        )}
+      </section>
+
+      <footer>
+        <span>Catalyst Router / Alpaca paper trading</span>
+        <span>Public data is delayed and is not investment advice.</span>
+      </footer>
+    </main>
+  );
+}
diff --git a/dashboard/lib/api.ts b/dashboard/lib/api.ts
new file mode 100644
