+  --blue: #165dcc;
+  --green: #08765a;
+  --amber: #9a5700;
+  --red: #b4232c;
+  --violet: #6941c6;
+  --mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
+  --sans: Inter, "Helvetica Neue", Arial, sans-serif;
+  --condensed: "Arial Narrow", "Aptos Narrow", var(--sans);
+}
+
+* { box-sizing: border-box; }
+
+html { background: var(--paper); color: var(--ink); }
+
+body {
+  margin: 0;
+  font-family: var(--sans);
+  background:
+    linear-gradient(90deg, transparent calc(50% - .5px), rgba(17,24,32,.035) 50%, transparent calc(50% + .5px)),
+    var(--paper);
+}
+
+main { max-width: 1480px; margin: 0 auto; padding: 0 40px 30px; }
+
+.masthead {
+  min-height: 150px;
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  padding: 28px 0 22px;
+  border-bottom: 2px solid var(--ink);
+}
+
+.eyebrow, .section-heading p {
+  margin: 0 0 8px;
+  font: 700 11px/1 var(--mono);
+  letter-spacing: .12em;
+  text-transform: uppercase;
+  color: var(--muted);
+}
+
+h1, h2, h3 { font-family: var(--condensed); text-transform: uppercase; margin: 0; }
+h1 { font-size: clamp(48px, 7vw, 94px); letter-spacing: -.055em; line-height: .78; }
+h2 { font-size: clamp(25px, 3.2vw, 46px); letter-spacing: -.035em; line-height: .95; }
+
+.publication { display: grid; justify-items: end; gap: 5px; font: 11px/1.25 var(--mono); }
+.publication strong { color: var(--red); letter-spacing: .14em; }
+
+.connection-error {
+  margin: 0;
+  padding: 10px 14px;
+  color: #fff;
+  background: var(--red);
+  font: 12px/1.4 var(--mono);
+}
+
+.authority {
+  display: grid;
+  grid-template-columns: minmax(260px, 1fr) 2fr;
+  min-height: 160px;
+  border-bottom: 1px solid var(--ink);
+}
+
+.authority-primary { display: flex; flex-direction: column; justify-content: center; padding: 24px 0; }
+.authority-primary span, dt { font: 11px/1.2 var(--mono); color: var(--muted); text-transform: uppercase; letter-spacing: .08em; }
+.authority-primary strong { font: 800 clamp(44px, 6vw, 82px)/.9 var(--condensed); }
+.mode-running .authority-primary strong { color: var(--green); }
+.mode-paused .authority-primary strong { color: var(--amber); }
+.mode-risk_halted .authority-primary strong, .mode-killed .authority-primary strong { color: var(--red); }
+.authority dl { margin: 0; display: grid; grid-template-columns: 1fr 1fr 1.4fr; }
+.authority dl div { display: flex; flex-direction: column; justify-content: center; gap: 10px; padding: 20px; border-left: 1px solid var(--rule); }
+.authority dd { margin: 0; font: 600 14px/1.4 var(--mono); }
+
+section { padding: 46px 0; border-bottom: 1px solid var(--ink); }
+.section-heading { margin-bottom: 34px; }
+
+.performance { display: grid; grid-template-columns: repeat(12, 1fr); column-gap: 24px; }
+.performance .section-heading { grid-column: 1 / -1; }
+.chart-placeholder { grid-column: span 8; position: relative; min-height: 280px; border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule); }
+.chart-placeholder svg { width: 100%; height: 220px; }
+.chart-placeholder span { font: 11px/1.4 var(--mono); color: var(--muted); }
+.grid-line { stroke: var(--rule); stroke-width: 1; fill: none; }
+.ghost-line { stroke: var(--blue); stroke-width: 3; fill: none; stroke-dasharray: 8 8; opacity: .35; }
+.headline-metrics { grid-column: span 4; margin: 0; border-top: 1px solid var(--ink); }
+.headline-metrics div { display: flex; align-items: baseline; justify-content: space-between; padding: 18px 0; border-bottom: 1px solid var(--rule); }
+.headline-metrics dd { margin: 0; font: 500 26px/1 var(--mono); }
+
+.risk-rulers { display: grid; gap: 16px; }
+.risk-row { display: grid; grid-template-columns: 170px 1fr 105px; gap: 16px; align-items: center; font: 12px/1 var(--mono); }
+.risk-track { height: 10px; background: #dcd8cc; position: relative; }
+.risk-track::after { content: ""; position: absolute; right: 0; top: -4px; width: 2px; height: 18px; background: var(--red); }
+.risk-track i { display: block; height: 100%; background: var(--blue); }
+.risk-row b { text-align: right; }
+
+.routes { display: grid; grid-template-columns: 2fr 1fr; column-gap: 60px; }
+.routes .section-heading { grid-column: 1 / -1; }
+.route-list { display: grid; gap: 17px; }
+.route-row { display: grid; grid-template-columns: 190px 1fr 45px 90px; gap: 12px; align-items: center; font: 11px/1 var(--mono); }
+.route-row > div { height: 14px; background: #dcd8cc; }
+.route-row i { display: block; height: 100%; background: var(--blue); }
+.route-no_trade i { background: var(--muted); }
+.route-row b { text-align: right; }
+.route-row em { color: var(--muted); font-style: normal; text-align: right; }
+.routes aside { border-left: 1px solid var(--rule); padding-left: 28px; display: grid; grid-template-columns: 110px 1fr; align-content: center; gap: 14px; font: 12px/1.3 var(--mono); }
+.routes aside strong:last-of-type { color: var(--violet); }
+
+.positions p, .empty-timeline { margin: 0; padding: 24px 0; font: 13px/1.5 var(--mono); color: var(--muted); border-top: 1px solid var(--rule); }
+
+.timeline ol { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--ink); }
+.timeline li { display: grid; grid-template-columns: 210px 1fr 220px; gap: 28px; padding: 24px 0 24px 28px; border-bottom: 1px solid var(--rule); position: relative; }
+.timeline li::before { content: ""; position: absolute; left: 3px; top: 29px; width: 9px; height: 9px; border: 2px solid var(--paper); outline: 1px solid var(--blue); background: var(--blue); transform: rotate(45deg); }
+.timeline li::after { content: ""; position: absolute; left: 7px; top: 40px; bottom: -29px; width: 1px; background: var(--rule); }
+.timeline li:last-child::after { display: none; }
+.timeline time, .timeline code, .decision-type { font: 11px/1.35 var(--mono); }
+.decision-type { color: var(--blue); text-transform: uppercase; }
+.timeline h3 { font-size: 24px; margin-top: 6px; }
+.timeline p { margin: 5px 0 0; color: var(--muted); line-height: 1.45; }
+.timeline code { align-self: center; text-align: right; color: var(--muted); }
+
+footer { display: flex; justify-content: space-between; padding: 22px 0 0; color: var(--muted); font: 10px/1.4 var(--mono); text-transform: uppercase; letter-spacing: .06em; }
+
+@media (max-width: 800px) {
+  main { padding: 0 18px 24px; }
+  .masthead { min-height: 125px; align-items: flex-start; flex-direction: column; gap: 24px; }
+  .publication { justify-items: start; }
+  .authority { grid-template-columns: 1fr; }
+  .authority dl { grid-template-columns: 1fr; }
+  .authority dl div { border-left: 0; border-top: 1px solid var(--rule); padding: 15px 0; }
+  .performance { display: block; }
+  .chart-placeholder { margin-bottom: 24px; min-height: 240px; }
+  .risk-row { grid-template-columns: 110px 1fr; }
+  .risk-row b { grid-column: 2; }
+  .routes { display: block; }
+  .route-row { grid-template-columns: 1fr 46px; }
+  .route-row > div { grid-column: 1 / -1; grid-row: 2; }
+  .route-row em { grid-column: 1; text-align: left; }
+  .routes aside { margin-top: 32px; border-left: 0; border-top: 1px solid var(--rule); padding: 20px 0 0; }
+  .timeline li { grid-template-columns: 1fr; gap: 10px; padding-left: 25px; }
+  .timeline code { text-align: left; }
+  footer { flex-direction: column; gap: 8px; }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; }
+}
