  name              = "/ecs/${local.name_prefix}/trader"
  retention_in_days = 30
  log_group_class   = "STANDARD"
  skip_destroy      = true
}

metadata.preview:
provider "aws" {
  region              = var.aws_region
  allowed_account_ids = [var.aws_account_id]

  default_tags {
    tags = {
      Project     = "catalyst-router"
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

